import nki
import nki.isa as nisa
import nki.language as nl

@nki.jit
def tensor_transpose2D_kernel_(x, shape2D):
    P, F = x.shape
    F1, F2 = shape2D
    assert F1 * F2 == F, f"shape2D {shape2D} does not match the free size {F}"

    tile = nl.ndarray((128, F2), dtype=nl.float32, buffer=nl.sbuf)
    out = nl.ndarray((P, F), dtype=nl.float32, buffer=nl.shared_hbm)

    for p in nl.affine_range(P):
        for f1 in nl.affine_range(F1):
            for f2 in nl.affine_range(F2):
                tile[f1, f2] = x[p, f1 * F2 + f2]

    for p in nl.affine_range(P):
        for f2 in nl.affine_range(F2):
            for f1 in nl.affine_range(F1):
                out[p, f1 * F2 + f2] = tile[f2, f1]

    return out

